-- docs/csat-learner/v62/lm-g1/db-query.sql
-- Read-only catalog/aggregate audit; never applies a migration.
select jsonb_build_object('objects',(select jsonb_agg(jsonb_build_object('name',name,'exists',to_regclass('public.'||name) is not null)) from unnest(array['csat_map_goal_version','learner_workspace','learner_workspace_plan','learning_first_attempts','learning_sessions','learning_task_attempts','content_qualification','content_release_approval','workspace_content_demand','workspace_content_order','workspace_content_delivery','workspace_material_demand','workspace_material_order','workspace_delivery_record','textbook_rung_level','textbook_rung_type']) as name),'rpcs',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition_md5',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'auth_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'),'vocab_branch',case when p.proname='grade_dcp_item' then position('vocab_choice' in p.prosrc)>0 else null end)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('learning_attempt_submit','csat_map_goal_set','learner_workspace_plan_commit','textbook_practice_items','textbook_practice_items_for','grade_dcp_item')),'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable) order by table_name,ordinal_position) from information_schema.columns where table_schema='public' and table_name in ('csat_map_goal','csat_map_goal_version','learner_workspace_plan')),'goal_constraints',(select jsonb_agg(pg_get_constraintdef(oid)) from pg_constraint where conrelid='public.csat_map_goal_version'::regclass),'counts',(select jsonb_build_object('workspace',(select count(*) from public.learner_workspace),'plan_versions',(select count(*) from public.learner_workspace_plan),'goal_versions',(select count(*) from public.csat_map_goal_version))),'applications',(select jsonb_agg(a) from (select surface,status,split_part(surface_ref,':',1) as task_or_line,coalesce(audience->>'role','unspecified') as role,count(*) as n from public.knowledge_applications where surface in ('csat_item_task','learning_map_find') group by 1,2,3,4 order by 1,2,3,4)a),'policies',(select jsonb_agg(jsonb_build_object('table',tablename,'command',cmd,'roles',roles,'using',qual)) from pg_policies where schemaname='public' and tablename in ('learning_task_attempts','learning_sessions','learner_workspace','learner_workspace_plan','csat_map_goal_version'))) as audit;
